mapper.select:
SELECT a.*, e.emp_no, e.name AS employee_name, d.name AS dept_name
FROM hr_attendance a
JOIN hr_employee e ON e.id = a.employee_id
LEFT JOIN sys_dept d ON d.id = e.dept_id


        (e.emp_no LIKE CONCAT('%', #{keyword}, '%') OR e.name LIKE CONCAT('%', #{keyword}, '%'))


        AND e.dept_id IN #{d}

    AND a.status = #{status}


        AND NOT (a.work_date = #{awaitingDay} AND a.check_in IS NOT NULL AND a.check_out IS NULL)

    AND a.work_date >= #{beginDate}
    AND a.work_date <= #{endDate}

ORDER BY a.work_date DESC, e.emp_no

SELECT * FROM hr_attendance
WHERE work_date BETWEEN #{from} AND #{to}
  AND employee_id IN #{id}
